/// <summary>
/// CB166_SalesOrderSubstitutes
/// Batch service class for Post sales order creation processing
/// </summary>
class METSysMessageProcessorService extends SysOperationServiceBase
{
    Batch                           batchTaskCurrent;
    BatchHeader                     batchHeader;
    RefRecId                        batchJobId;
    RefRecId                        headerTaskId;
    boolean                         isExecutingInBatch;

    private guid topPickingProcessId;

}

Method.Source:
/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METSysOperationTaskDataContract</c>
/// </param>
public void process(METSysMessageProcessorContract _contract)
{
    batchTaskCurrent    = this.getCurrentBatchTask();
    batchJobId          = batchTaskCurrent.BatchJobId;
    headerTaskId        = batchTaskCurrent.RecId;
    batchHeader         = BatchHeader::construct(batchJobId);
    isExecutingInBatch  = batchTaskCurrent ? true : false;

    // Load the queue for tasks
    int numMessages = this.processSysMessage(_contract.parmMessageQueue());

    this.createTopPickingTasks(_contract, numMessages);
}

/// <summary>
/// Create top picking tasks based on the number of messages in the queue and the max tasks allowed for the message processor
/// </summary>
/// <param name = "_contract"><c>METSysMessageProcessorContract</c> contract</param>
/// <param name = "_numMessages">The number of messages in the queue to process</param>
private void createTopPickingTasks(METSysMessageProcessorContract _contract, int _numMessages)
{
    SysOperationServiceController   controller;
    SysMessageQueue messageQueue = _contract.parmMessageQueue();
    SysMessageQueueMetadata messageQueueMetadata = SysMessageQueueMetadata::construct(messageQueue);
    METSysMessageProcessorContract taskDataContract;

    int maxTasks = messageQueueMetadata.getMessageProcessorsTasks();

    // Bug 411365: DR2 PVT - SO - Priced Orders stuck in the processor queue
    // This is to avoid creating 80 tasks when there is nothing in the queue
    // OR if less messages than the max messageQueueMetadata, creates less batch tasks to avoid creating empty tasks
    maxTasks = _numMessages < maxTasks ? _numMessages : maxTasks;        

    if (isExecutingInBatch && maxTasks)
    {
        for (int i = 1; i <= maxTasks; i++)
        {
            controller = new SysOperationServiceController(classStr(METSysMessageProcessorTaskService), methodStr(METSysMessageProcessorTaskService, process));
            controller.parmDialogCaption("MET Message processor - Top picking POC task");

            // grab contract instance from controller, use same contract
            taskDataContract = controller.getDataContractObject();
            taskDataContract.parmMessageQueue(messageQueue);
            taskDataContract.parmIsMainBatchTask(i==1);
            taskDataContract.parmTopPickingProcessId(topPickingProcessId);

            //Bug 174941 - CB-166 Custom top picking batch jobs with recurrence keeps creating new batch tasks
            batchHeader.addRuntimeTask(controller, headerTaskId);
        }

        // Do not overwrite the user's batch job name from the class method
        // Was not there in old service classes from METPriceDataFeedService
        //batchHeader.parmCaption(this.getTaskServiceCaption());
        batchHeader.save();
    }
}

/// <summary>
/// Insert message processor recIds into the METPEPricingTopPickingQueue table for processing
/// </summary>
/// <param name = "_messageQueue"><c>SysMessageQueue</c> object representing the message queue</param>
/// <returns>The number of messages inserted</returns>
int processSysMessage(SysMessageQueue _messageQueue)
{
    RecordInsertList pricingTopPickingQueueList;
    SysMessage message;
    SysMessageProcessingState messageProcessingState;
    int numMessages;
    #OCCRetryCount

    METPEPricingTopPickingQueue::cleanUpPricingTopPickingQueue();
    pricingTopPickingQueueList = new RecordInsertList(tableNum(METPEPricingTopPickingQueue));
    topPickingProcessId = newGuid();

    while select RecId
        from message
            exists join messageProcessingState
        where  messageProcessingState.Message == message.RecId
            && message.MessageQueue == _messageQueue
            && messageProcessingState.State == SysMessageState::Queued            
    {
        try
        {              
            this.addToPricingTopPickingQueueList(
                pricingTopPickingQueueList,
                message.RecId);   

            numMessages++;
        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::Deadlock;
            }
            else
            {
                retry;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        catch (Exception::Error)
        {
            // catch the errors so processing can continue
            curext(); // avoids a warning about an empty block
        }
    }

    this.insertIntoTopPickingQueue(pricingTopPickingQueueList);

    return numMessages;
}

/// <summary>
/// Adding sales order to process into the RecordInsertList
/// </summary>
/// <param name = "_journalPostQueueList"><c>RecordInsertList</c> object</param>
/// <param name = "_salesId">Sales order number</param>
private void addToPricingTopPickingQueueList(RecordInsertList _pricingTopPickingQueueList, SysMessageRecId _messageRecId)
{
    METPEPricingTopPickingQueue pricingTopPickingQueue;
    pricingTopPickingQueue.ProcessId = this.topPickingProcessId;
    pricingTopPickingQueue.MessageRecId = _messageRecId;

    _pricingTopPickingQueueList.add(pricingTopPickingQueue);
}

/// <summary>
/// Buld insert from RecordInsertList into <c>METPostPricingOrderOptimisationQueue</c>
/// </summary>
/// <param name = "_postPricingOrderOptimisationQueueList">RecordInsertList to bulk insert</param>
private void insertIntoTopPickingQueue(RecordInsertList _pricingTopPickingQueueList)
{
    _pricingTopPickingQueueList.insertDatabase();
}
